std::unordered_set<typename Triangulation::Face_handle, typename Triangulation::Face_hash> visited;

// Initialize: find an exterior face (unconstrained or on boundary)
typename Triangulation::Face_handle initial_face;
bool found_exterior = false;
for (auto fit = triangulation.faces_begin(); fit != triangulation.faces_end(); ++fit) {
    bool has_constraint_edge = false;
    for (int i = 0; i < 3; ++i) {
        if (triangulation.is_constrained(*fit, i)) {
            has_constraint_edge = true;
            break;
        }
    }
    if (!has_constraint_edge) {
        initial_face = fit;
        found_exterior = true;
        break;
    }
}

if (!found_exterior) {
    // If all faces are constrained, pick any face and mark as interior
    initial_face = triangulation.faces_begin();
}

initial_face->info().is_interior = false; // Mark as exterior
queue.push(initial_face);
visited.insert(initial_face);

while (!queue.empty()) {
    auto current = queue.front();
    queue.pop();

    for (int i = 0; i < 3; ++i) {
        auto neighbor = current->neighbor(i);
        if (triangulation.is_constrained(current, i)) {
            // Constraint edge: do not propagate across
            continue;
        }

        if (visited.find(neighbor) == visited.end()) {
            neighbor->info().is_interior = !current->info().is_interior;
            visited.insert(neighbor);
            queue.push(neighbor);
        }
    }
}

// For faces not reached (e.g., isolated constrained regions), mark as interior by default
for (auto fit = triangulation.faces_begin(); fit != triangulation.faces_end(); ++fit) {
    if (visited.find(fit) == visited.end()) {
        fit->info().is_interior = true;
    }
}

